import{_ as a,c as l,o as i,a4 as e}from"./chunks/framework.CpVK_f0P.js";const m=JSON.parse('{"title":"每日训练流程","description":"","frontmatter":{},"headers":[],"relativePath":"method/daily-workflow.md","filePath":"method/daily-workflow.md"}'),s={name:"method/daily-workflow.md"},n=e(`<h1 id="每日训练流程" tabindex="-1">每日训练流程 <a class="header-anchor" href="#每日训练流程" aria-label="Permalink to &quot;每日训练流程&quot;">​</a></h1><h2 id="核心流程" tabindex="-1">核心流程 <a class="header-anchor" href="#核心流程" aria-label="Permalink to &quot;核心流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>听材料</span></span>
<span class="line"><span>→ 理解内容</span></span>
<span class="line"><span>→ 第一次复述</span></span>
<span class="line"><span>→ 检查错误</span></span>
<span class="line"><span>→ 提炼 3～5 个表达</span></span>
<span class="line"><span>→ 替换造句</span></span>
<span class="line"><span>→ 第二次复述</span></span>
<span class="line"><span>→ 隔天复习</span></span></code></pre></div><h2 id="每日执行方式-20-30-分钟" tabindex="-1">每日执行方式（20～30 分钟） <a class="header-anchor" href="#每日执行方式-20-30-分钟" aria-label="Permalink to &quot;每日执行方式（20～30 分钟）&quot;">​</a></h2><h3 id="第一阶段-听和理解-5-8-分钟" tabindex="-1">第一阶段：听和理解（5～8 分钟） <a class="header-anchor" href="#第一阶段-听和理解-5-8-分钟" aria-label="Permalink to &quot;第一阶段：听和理解（5～8 分钟）&quot;">​</a></h3><ol><li>选一段 1～3 分钟的材料（如《走遍美国》某一节）</li><li>先不看文本，听 1～2 遍，抓大意</li><li>遇到听不懂的地方，看文本确认</li><li>确保没有不认识的关键词</li></ol><h3 id="第二阶段-第一次复述-5-分钟" tabindex="-1">第二阶段：第一次复述（5 分钟） <a class="header-anchor" href="#第二阶段-第一次复述-5-分钟" aria-label="Permalink to &quot;第二阶段：第一次复述（5 分钟）&quot;">​</a></h3><ol><li>关掉材料，用自己的话复述刚才听到的内容</li><li>可以录音，方便回听</li><li>不追求完美，先说出来</li></ol><h3 id="第三阶段-检查和提炼-5-8-分钟" tabindex="-1">第三阶段：检查和提炼（5～8 分钟） <a class="header-anchor" href="#第三阶段-检查和提炼-5-8-分钟" aria-label="Permalink to &quot;第三阶段：检查和提炼（5～8 分钟）&quot;">​</a></h3><ol><li>回听录音或回忆复述过程，找出问题： <ul><li>哪里卡住了？</li><li>哪里用了中文思维？</li><li>哪里时态搞错了？</li><li>哪个词不确定？</li></ul></li><li>从材料中提炼 3～5 个值得练习的表达</li><li>每个表达用自己的场景造 2～3 个替换句</li></ol><h3 id="第四阶段-第二次复述-5-分钟" tabindex="-1">第四阶段：第二次复述（5 分钟） <a class="header-anchor" href="#第四阶段-第二次复述-5-分钟" aria-label="Permalink to &quot;第四阶段：第二次复述（5 分钟）&quot;">​</a></h3><ol><li>重新复述同一段内容</li><li>尝试主动使用刚刚提炼的表达</li><li>对比两次复述的差异</li></ol><h3 id="隔天复习" tabindex="-1">隔天复习 <a class="header-anchor" href="#隔天复习" aria-label="Permalink to &quot;隔天复习&quot;">​</a></h3><ul><li>第二天花 3～5 分钟重新复述同一段内容</li><li>检查重点表达是否还能主动使用</li><li>一周后再复述一次，确认掌握程度</li></ul><h2 id="工作场景训练-可选-额外-15-20-分钟" tabindex="-1">工作场景训练（可选，额外 15～20 分钟） <a class="header-anchor" href="#工作场景训练-可选-额外-15-20-分钟" aria-label="Permalink to &quot;工作场景训练（可选，额外 15～20 分钟）&quot;">​</a></h2><p>如果时间允许，可以在上述训练之外加入工作场景练习：</p><ul><li>周一/四：Stand-up 站会汇报</li><li>周二/五：描述 Bug / 技术问题</li><li>周三/六：技术讨论 / 确认需求</li><li>周日：自由复习或休息</li></ul><p>每个场景的训练方式：写下内容 → 脱稿说出来 → 录音 → 回听纠正 → 再录一遍。</p>`,18),o=[n];function t(r,h,p,d,c,u){return i(),l("div",null,o)}const b=a(s,[["render",t]]);export{m as __pageData,b as default};
